                    item = new EditorChoice("Uncoupled Temperature-displacement Step");
                    UncoupledTempDispStep uncoupledTempDispStep = new UncoupledTempDispStep(GetStepName());
                    uncoupledTempDispStep.SolverType = defaultSolverType;
