                }
            }

        }
private Step CreateNewOrCloneLast(Type stepTypeToCreate)
        {
            if (stepTypeToCreate == null) throw new ArgumentNullException();
            //
            Step newStep;
            Step prevOrLastStep = GetPreviousOrLastStep();
            //
            if (prevOrLastStep == null || prevOrLastStep.GetType() != stepTypeToCreate)
            {
                newStep = (Step)Activator.CreateInstance(stepTypeToCreate, new object[] { GetStepName() });
                //
                if (prevOrLastStep != null)
                {
                    if (newStep.IsPerturbationSupported()) newStep.Perturbation = prevOrLastStep.Perturbation;
                    else newStep.Perturbation = false;
                    //
                    newStep.Nlgeom = prevOrLastStep.Nlgeom;
                    newStep.MaxIncrements = prevOrLastStep.MaxIncrements;
                    newStep.IncrementationType = prevOrLastStep.IncrementationType;
                    newStep.SolverType = prevOrLastStep.SolverType;
                }
            }
            else
            {
                newStep = prevOrLastStep.DeepClone();
                //
                newStep.Active = true;
                newStep.BoundaryConditions.Clear(); // this gets added at the step collection
                newStep.Loads.Clear();              // this gets added at the step collection
                newStep.DefinedFields.Clear();      // this gets added at the step collection
                //
                newStep.Name = GetStepName();
            }
            return newStep;
        }
private Step GetPreviousOrLastStep()
        {
            Step prevOrLastStep = null;
            // Find previous step
            if (_stepToEditName != null)
            {
                Step[] steps = _controller.GetAllSteps();
                int prevStepId = -1;
                for (int i = 0; i < steps.Length; i++)
                {
                    if (steps[i].Name == _stepToEditName)
                    {
                        prevStepId = i - 1;
                        break;
                    }
                }
                if (prevStepId >= 0) prevOrLastStep = steps[prevStepId];
            }
            // Find last step
            else if (_stepNames.Length > 0)
            {
                prevOrLastStep = _controller.GetAllSteps().Last();
            }
            //
            return prevOrLastStep;
        }
private bool IsCyclicSymmetryActive(out CyclicSymmetry cyclicSymmetry)
        {
            foreach (var entry in _controller.Model.Constraints)
            {
                if (entry.Value is CyclicSymmetry candidate && candidate.Active)
                {
                    cyclicSymmetry = candidate;
                    return true;
                }
            }
            cyclicSymmetry = null;
            return false;
        }
private void ValidateCyclicSymmetryModes(FrequencyStep frequencyStep)
        {
            CyclicSymmetry cyclicSymmetry = null;
            bool containsAxisNodes = false;
            foreach (var entry in _controller.Model.Constraints)
            {
                if (entry.Value is CyclicSymmetry candidate && candidate.Active)
                {
                    if (cyclicSymmetry == null) cyclicSymmetry = candidate;
                    containsAxisNodes |= _controller.CyclicSymmetryContainsAxisNodes(candidate);
                }
            }
            if (cyclicSymmetry != null)
            {
                _controller.Model.CheckCyclicSymmetryCompatibility(cyclicSymmetry, cyclicSymmetry.Name);
                frequencyStep.CheckCyclicSymmetryModes(cyclicSymmetry.NumberOfSectors, containsAxisNodes);
            }
        }
private void ValidateStepValues(Step step)
        {
            if (step is BuckleStep buckleStep)
            {
                if (!(buckleStep.Accuracy > 0) || double.IsInfinity(buckleStep.Accuracy))
                    throw new CaeException("The accuracy of the buckle step must be a positive finite number.");
            }
            else if (step is ModalDynamicsStep modalDynamicsStep)
                ValidateModalDamping(modalDynamicsStep.ModalDamping);
            else if (step is SteadyStateDynamicsStep steadyStateDynamicsStep)
            {
                if (!steadyStateDynamicsStep.Harmonic &&
                    steadyStateDynamicsStep.TimeLower > steadyStateDynamicsStep.TimeUpper)
                    throw new CaeException("The lower time " + steadyStateDynamicsStep.TimeLower + " exceeds the " +
                                           "upper time " + steadyStateDynamicsStep.TimeUpper + ".");
                ValidateModalDamping(steadyStateDynamicsStep.ModalDamping);
            }
        }
private void ValidateModalDamping(ModalDamping modalDamping)
        {
            if (modalDamping == null || modalDamping.DampingType != ModalDampingTypeEnum.Direct) return;
            //
            List<CaeJob.DampingRatioAndRange> ranges = modalDamping.DampingRatiosAndRanges;
            if (ranges == null || ranges.Count == 0)
                throw new CaeException("The Direct modal damping needs at least one damping ratio and mode range.");
            for (int i = 0; i < ranges.Count; i++)
            {
                if (ranges[i].LowestMode < 1)
                    throw new CaeException("Damping ratio row " + (i + 1) + ": the lowest mode must be at least 1.");
                if (ranges[i].HighestMode < ranges[i].LowestMode)
                    throw new CaeException("Damping ratio row " + (i + 1) + ": the highest mode value must be equal " +
                                           "or larger than the lowest mode value.");
            }
        }
private string GetStepName()
        {
            return _stepNames.GetNextNumberedKey("Step");
        }
}

