// Source PrePoMax/Forms/21_FEModel/FrmModelProperties.cs SHA256 a6d1f1367f12a4a979261fe18bfe01bc05413d4a4b590e92c9bbf71efa1178de
public sealed class ModelPropertiesRule : FormRule {
 ViewModelProperties _viewModelProperties;
 public ModelPropertiesRule(Controller controller,string step,string name):base(controller,step,name) {
  _viewModelProperties=new ViewModelProperties(controller.Model.Properties.DeepClone());
  _viewModelProperties.Name=controller.Model.Name;SelectedObject=_viewModelProperties;
 }
 public override object Item=>_viewModelProperties.GetBase();
 protected override void OnSelect(object value)=>throw new NotSupportedException();
protected override void OnApply(bool onOkAddNew)
        {
            _viewModelProperties = (ViewModelProperties)SelectedObject;
            // The Python API refuses these names, so a journal of the dialog could not set them again. A stored name
            // the dialog did not change is kept as it is
            string name = _viewModelProperties.Name;
            if (name != _controller.Model.Name)
            {
                if (name == null || name.Trim().Length == 0)
                    throw new CaeException("The model name must not be empty.");
                if (name.Trim().Length != name.Length)
                    throw new CaeException("The model name must not start or end with a space: '" + name + "'.");
            }
            //
            if (_viewModelProperties.ModelType == ModelType.Submodel)
            {
                string fileName = _viewModelProperties.GlobalResultsFileName;
                fileName = System.IO.Path.Combine(_controller.Settings.GetWorkDirectory(), fileName);
                //
                if (!System.IO.File.Exists(fileName))
                    throw new CaeException("The selected global results file " + fileName +" does not exist.");
            }
            else if (_viewModelProperties.ModelType == ModelType.SlipWearModel)
            {
                ModelProperties modelProperties = _viewModelProperties.GetBase();
                if (modelProperties.NumberOfCycles.Value % modelProperties.CyclesIncrement.Value != 0)
                    throw new CaeException("The number of slip wear cycles must be a multiple of the cycles increment.");
            }
            // Replace
            if (_propertyItemChanged)
            {
                _controller.ReplaceModelPropertiesCommand(_viewModelProperties.Name, _viewModelProperties.GetBase());
            }
        }
}

// Source PrePoMax/Forms/00_Parameters/FrmEquationParameters.cs SHA256 026ed96143a2826c35a71c754d75599ee021662fc38cac5678f098e62477bd7d
public sealed class ParameterEditSession {
 readonly Controller _controller;
 readonly List<ViewEquationParameter> _parameters=[];
 readonly Dictionary<string,object> _propertyParameters;
 readonly HashSet<string> _unusableNames=new(StringComparer.OrdinalIgnoreCase);
 public ParameterEditSession(Controller controller) {
  _controller=controller;_propertyParameters=controller.GetPropertyParameters();
  _unusableNames.UnionWith(MyNCalc.GetReservedParameterNames());_unusableNames.UnionWith(_propertyParameters.Keys);
  foreach(var entry in controller.Model.Parameters)_parameters.Add(new ViewEquationParameter(entry.Value));
  EvaluateParameters();
 }
 public CollectionSheet Table=>new(_parameters);
 public void Evaluate()=>EvaluateParameters();
 public void Cancel()=>_controller.UpdateNCalcParameters(false);
 public void Commit(){

                //
                EvaluateParameters();
                int errorRow = GetFirstErrorRow();
                if (errorRow >= 0)
                {

                    string name = _parameters[errorRow].Name;
                    string message = name.Length > 0 ? "The parameter '" + name + "' cannot be used."
                                                     : "The parameter in row " + (errorRow + 1) + " cannot be used.";
                    throw new CaeException(message + Environment.NewLine + _parameters[errorRow].Error);
                }
                // The values the user typed replace the ones a batch run overrode
                _controller.Model.Parameters.OverriddenParameters.Clear();
                //
                List<EquationParameter> parameters = new List<EquationParameter>();
                foreach (ViewEquationParameter parameter in _parameters) parameters.Add(parameter.GetParameter());
                // The whole table is one command: applied one parameter at a time, an intermediate state
                // would hold an equation whose parameter is renamed, removed or not added yet
                if (AreParametersChanged(parameters)) _controller.SetParametersCommand(parameters.ToArray());
                //

                _controller.UpdateNCalcParameters(false);
}
private void EvaluateParameters()
        {
            if (_parameters == null) return;
            //
            double value;
            string error;
            HashSet<string> usedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            List<KeyValuePair<string, string>> nameEquations = new List<KeyValuePair<string, string>>();
            Dictionary<int, string> nameErrors = new Dictionary<int, string>();
            // A row whose name cannot be used is not given to the resolver, it is reported on its own
            for (int i = 0; i < _parameters.Count; i++)
            {
                error = GetNameError(_parameters[i].Name);
                if (error == null && !usedNames.Add(_parameters[i].Name))
                    error = GetDuplicateNameError(_parameters[i].Name);
                //
                if (error != null) nameErrors.Add(i, error);
                else nameEquations.Add(new KeyValuePair<string, string>(_parameters[i].Name, _parameters[i].Equation));
            }
            //
            Dictionary<string, double> values;
            Dictionary<string, string> errors = EquationParameterResolver.Evaluate(nameEquations, _propertyParameters,
                                                                                   out values);
            //
            HashSet<string> autocompleteItems = new HashSet<string>(_propertyParameters.Keys);
            for (int i = 0; i < _parameters.Count; i++)
            {
                if (nameErrors.TryGetValue(i, out error)) _parameters[i].SetError(error);
                else if (errors.TryGetValue(_parameters[i].Name, out error)) _parameters[i].SetError(error);
                else if (values.TryGetValue(_parameters[i].Name, out value))
                {
                    _parameters[i].SetValue(value);
                    autocompleteItems.Add(_parameters[i].Name);
                }
            }
            //



        }
private string GetNameError(string name)
        {
            string error = NamedClass.CheckNameError(name, null);
            if (error != null) return error;
            //
            if (char.IsDigit(name[0]))
                return "The parameter name '" + name + "' must not start with a digit.";
            if (_unusableNames.Contains(name))
                return "The parameter name '" + name + "' cannot be used since it is a reserved name.";
            //
            return null;
        }
private string GetDuplicateNameError(string name)
        {
            return "The parameter named '" + name + "' already exists.";
        }
private int GetFirstErrorRow()
        {
            for (int i = 0; i < _parameters.Count; i++)
            {
                if (_parameters[i].Error != null) return i;
            }
            //
            return -1;
        }
private bool AreParametersChanged(List<EquationParameter> parameters)
        {
            EquationParameterCollection existingParameters = _controller.Model.Parameters;
            if (existingParameters.Keys.Count != parameters.Count) return true;
            //
            int i = 0;
            foreach (var entry in existingParameters)
            {
                if (entry.Key != parameters[i].Name) return true;
                if (!entry.Value.EquationStr.EqualsEquation(parameters[i].EquationStr)) return true;
                if (entry.Value.Description != parameters[i].Description) return true;
                i++;
            }
            //
            return false;
        }
}

