 public bool ShowProperties(int index)=>true;
 public bool ShowTable(int index)=>false;
 public CollectionSheet Table(int index)=>null;
public bool Commit()
        {
            _stepControls = new StepControls();
            foreach (EditorChoice item in choices)
            {
                _stepControls.AddParameter(((ViewStepControlParameter)(item.Tag)).Base);
            }
            // Replace
            bool applyControls = false;
            string message = "Customized solution controls are not needed in most nonlinear analyses." +
                             " They should only be used by those users who know what they are doing and" +
                             " are expert in the field.";
            if (_propertyItemChanged)
            {
                if (_showWarning)
                {
                    if (MessageBoxes.ShowWarningQuestionOKCancel(message) == DialogResult.OK)
                    {
                        applyControls = true;
                        _showWarning = false;
                    }
                }
                else applyControls = true;
            }
            else return true;   // nothing changed
            //
            if (applyControls)
            {
                _controller.ReplaceStepControlsCommand(_stepName, StepControls);
                return true;
            }
            else return false;
        }
}

public static class FormRules
{
 public static FormRule Create(string family,Controller controller,string step,string name) => family switch {
"Node sets" => new FrmNodeSetRule(controller,step,name),
"Element sets" => new FrmElementSetRule(controller,step,name),
"Surfaces" => new FrmSurfaceRule(controller,step,name),
"Reference points" => new FrmReferencePointRule(controller,step,name),
"Coordinate systems" => new FrmCoordinateSystemRule(controller,step,name),
"Sections" => new FrmSectionRule(controller,step,name),
"Constraints" => new FrmConstraintRule(controller,step,name),
"Contact pairs" => new FrmContactPairRule(controller,step,name),
"Distributions" => new FrmDistributionRule(controller,step,name),
"Amplitudes" => new FrmAmplitudeRule(controller,step,name),
"Initial conditions" => new FrmInitialConditionRule(controller,step,name),
"Steps" => new FrmStepRule(controller,step,name),
"History outputs" => new FrmHistoryOutputRule(controller,step,name),
"Field outputs" => new FrmFieldOutputRule(controller,step,name),
"Boundary conditions" => new FrmBCRule(controller,step,name),
"Loads" => new FrmLoadRule(controller,step,name),
"Defined fields" => new FrmDefinedFieldRule(controller,step,name),
"Model properties" => new ModelPropertiesRule(controller,step,name),
 _=>throw new ArgumentException("No original form adapter for "+family)
 };
}
